73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /** Maximum number of owners a single city may contain; creating an owner in a city that
79	     *  already has this many owners is rejected with 409 Conflict. */
80	    private static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /** Maximum number of owners that may be created on a single day (by registration date); creating
83	     *  an owner once this many owners already carry today's registration date is rejected with
84	     *  429 Too Many Requests. */
85	    private static final int MAX_OWNERS_PER_DAY = 100;
86	
87	    /** When more than this many owners already carry today's registration date at creation time, the
88	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
89	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
90	
91	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
92	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
93	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
94	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
97	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    private final TelephoneNormalizer telephoneNormalizer;
108	
109	    private final HouseholdNormalizer householdNormalizer;
110	
111	    private final AddressNormalizer addressNormalizer;
112	
113	    private final EmailNormalizer emailNormalizer;
114	
115	    /**
116	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
117	     * repeats with the same key returns the originally created owner (200) instead of creating a
118	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
119	     */
120	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
121	        new java.util.concurrent.ConcurrentHashMap<>();
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper,
127	                                 TelephoneNormalizer telephoneNormalizer,
128	                                 HouseholdNormalizer householdNormalizer,
129	                                 AddressNormalizer addressNormalizer,
130	                                 EmailNormalizer emailNormalizer) {
131	        this.clinicService = clinicService;
132	        this.ownerMapper = ownerMapper;
133	        this.petMapper = petMapper;
134	        this.visitMapper = visitMapper;
135	        this.telephoneNormalizer = telephoneNormalizer;
136	        this.householdNormalizer = householdNormalizer;
137	        this.addressNormalizer = addressNormalizer;
138	        this.emailNormalizer = emailNormalizer;
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
170	        // been used for a successful create, return the originally created owner with 200 OK instead
171	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
172	        // with 409). A first, unseen key runs the normal create and records its result under the key.
173	        String idempotencyKey = currentIdempotencyKey();
174	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
175	            return createOwner(ownerFieldsDto);
176	        }
177	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
178	        if (previouslyCreated != null) {
179	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
180	        }
181	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
182	        idempotentCreates.put(idempotencyKey, response.getBody());
183	        return response;
184	    }
185	
186	    /**
187	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
188	     * the request carries no such header (or there is no active servlet request). Reading it from the
189	     * request context here keeps the header — a request-level concern surrounding the create — out of
190	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
191	     *
192	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
193	     */
194	    private String currentIdempotencyKey() {
195	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
196	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
197	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
198	        }
199	        return null;
200	    }
201	
202	    /**
203	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
204	     * response for the newly persisted owner: the request fields are mapped and normalized, every
205	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
206	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
207	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
208	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
209	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
210	     * {@code addOwner} without disturbing the creation steps gathered here.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields
213	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
214	     */
215	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
218	        normalizeOwnerFields(owner);
219	        // Enforce the pre-persistence policies that can reject the new owner outright.
220	        rejectDisallowedOwnerCreation(owner);
221	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
222	        // function of last name and postcode), cap the membership level for a new household member,
223	        // and record the household size. The household id is no longer part of the identity key, so
224	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
225	        // by the identity-key check below and otherwise flagged as soft duplicates.
226	        boolean declaredHouseholdMember =
227	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
228	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
229	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
230	        // owner. This single rule subsumes the former separate telephone, email and household
231	        // duplicate checks.
232	        rejectWhenIdentityInUse(owner);
233	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
234	        // shares an existing owner's last name and postcode with a different telephone. A declared
235	        // household member is never flagged: it is a known member, not a suspected duplicate.
236	        assignPossibleDuplicate(owner, declaredHouseholdMember);
237	        // Assign the remaining create-time derived fields (namesake count, customer code,
238	        // membership number and bulk-signup warning), each fixed at creation time.
239	        assignDerivedFields(owner);
240	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
241	        // derived fields above because the level is computed from the membership points, which depend
242	        // on the namesake count assigned in assignDerivedFields.
243	        assignMembershipLevel(owner);
244	        this.clinicService.saveOwner(owner);
245	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
246	        // Emit an audit line for the successful create, carrying the owner id, customer code,
247	        // registration date, membership level and membership number so the create can be traced
248	        // from the dedicated AUDIT log.
249	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
250	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
251	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
252	        headers.setLocation(UriComponentsBuilder.newInstance()
253	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
254	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
255	    }
256	
257	    /**
258	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
259	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
260	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
261	     * the sequence of create-time rejections stays readable and a new rule is added as one more
262	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
263	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
264	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}.
265	     *
266	     * @param owner the newly mapped and normalized owner being created
267	     */
268	    private void rejectDisallowedOwnerCreation(Owner owner) {
269	        rejectWhenDailyLimitReached(owner);
270	        rejectWhenCityAtCapacity(owner);
271	    }
272	
273	    /**
274	     * Applies the household-membership rules for a newly normalized owner being created. The
275	     * household id is a deterministic function of the owner's last name and postcode, so owners
276	     * with the same last name and postcode share it automatically; it is assigned to the new owner
277	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
278	     * same last name and postcode is a member of the same household. A new owner may join an
279	     * existing household: rather than the create being rejected, the newcomer's membership level is
280	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
281	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
282	     * declared member and is never flagged as a possible duplicate. The owner's
283	     * {@code householdSize} (the number of owners sharing the household after this create) is
284	     * recorded either way.
285	     *
286	     * @param owner           the newly mapped and normalized owner being created
287	     * @param sharesHousehold whether the request declared that the owner shares an existing household
288	     * @return {@code true} if the owner joined an existing household as a declared member
289	     */
290	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
291	        // Assign the deterministic household id (a pure function of last name and postcode) so every
292	        // owner with the same last name and postcode shares it automatically.
293	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
294	        // Identify any existing owners in the same household (same computed household id). A new owner
295	        // may join an existing household: its membership level is capped at one above the household's
296	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
297	        List<Owner> householdMembers = sameHouseholdOwners(owner);
298	        // An owner that joins an existing household while the request declares it shares that
299	        // household is a known, declared member and so is never flagged as a possible duplicate.
300	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
301	        // Record the size of this owner's household after this create, fixed at creation time.
302	        owner.setHouseholdSize(householdMembers.size() + 1);
303	        return declaredHouseholdMember;
304	    }
305	
306	    /**
307	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
308	     * has already been resolved: the namesake count, the per-city customer code, the membership
309	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
310	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
311	     * here keeps {@link #addOwner} focused on the high-level create sequence.
312	     *
313	     * @param owner the owner being created, already normalized and with its household resolved
314	     */
315	    private void assignDerivedFields(Owner owner) {
316	        // Record how many existing owners already share this owner's first and last name
317	        // (compared case-insensitively) before this create, fixed at creation time.
318	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
319	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
320	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
321	        // time.
322	        owner.setCustomerCode(customerCode(owner));
323	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
324	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
325	        // creation time.
326	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
327	        // Flag the create when more than 80 owners have already been created on this owner's
328	        // (adjusted business-day) registration date, fixed at creation time.
329	        owner.setBulkSignupWarning(
330	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
331	    }
332	
333	    /**
334	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
335	     * time. The level a newly created owner would earn from their membership points cannot exceed
336	     * one above the current maximum membership level among their existing household members (the
337	     * owners already sharing this owner's household id); the capped value is stored so it is returned
338	     * unchanged on later reads. When the owner has no existing household member no cap applies and
339	     * the plain points-derived level is used.
340	     *
341	     * @param owner the owner being created, already normalized and with its derived fields assigned
342	     */
343	    private void assignMembershipLevel(Owner owner) {
344	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
345	        List<Owner> householdMembers = sameHouseholdOwners(owner);
346	        if (!householdMembers.isEmpty()) {
347	            int maxMemberLevel = householdMembers.stream()
348	                .mapToInt(this::memberLevel)
349	                .max()
350	                .getAsInt();
351	            level = Math.min(level, maxMemberLevel + 1);
352	        }
353	        owner.setMembershipLevel(level);
354	    }
355	
356	    /**
357	     * Returns an existing household member's membership level for the purpose of capping a new
358	     * member's level: the level stored on the member when present (the already-capped value fixed at
359	     * its own creation), otherwise the level derived from its membership points (for members created
360	     * before the level was persisted).
361	     *
362	     * @param member an existing owner in the same household
363	     * @return the member's membership level
364	     */
365	    private int memberLevel(Owner member) {
366	        return member.getMembershipLevel() != null
367	            ? member.getMembershipLevel()
368	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
369	    }
370	
371	    /**
372	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
373	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
374	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
375	     * this single rule replaces the former separate telephone, email and household duplicate checks:
376	     * two owners collide only when their whole keys are equal, and members of one household with
377	     * different telephones have different keys and are both allowed (instead flagged as soft
378	     * duplicates).
379	     *
380	     * @param owner the owner being created, already normalized
381	     */
382	    private void rejectWhenIdentityInUse(Owner owner) {
383	        String identityKey = owner.getIdentityKey();
384	        boolean inUse = existingOwners()
385	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
386	        if (inUse) {
387	            throw new DuplicateIdentityException(
388	                "An owner with identity key " + identityKey + " already exists");
389	        }
390	    }
391	
392	    /**
393	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
394	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
395	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
396	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
397	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
398	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
399	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
400	     * possible duplicate. A declared household member is never flagged: it is a known member of the
401	     * household, not a suspected duplicate. Both values are fixed at creation time.
402	     *
403	     * @param owner                   the owner being created, already normalized and confirmed not a
404	     *                                hard duplicate
405	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
406	     *                                member
407	     */
408	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
409	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
410	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
411	            .map(Owner::getId)
412	            .min(Integer::compareTo)
413	            .orElse(null);
414	        owner.setPossibleDuplicate(matchId != null);
415	        owner.setPossibleDuplicateOf(matchId);
416	    }
417	
418	    /**
419	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
420	     * two have different identity keys (an equal key would already have been rejected as a hard
421	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
422	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
423	     * duplicate of the existing one without rejecting the create.
424	     *
425	     * @param existing an existing owner to compare against
426	     * @param owner    the owner being created
427	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
428	     */
429	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
430	        return existing.getPostcode() != null
431	            && existing.getPostcode().equals(owner.getPostcode())
432	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
433	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
434	    }
435	
436	    /**
437	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
438	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
439	     *
440	     * @param owner the owner being created
441	     */
442	    private void rejectWhenDailyLimitReached(Owner owner) {
443	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
444	            throw new DailyOwnerLimitExceededException(
445	                "The maximum number of owners that may be created today has already been reached");
446	        }
447	    }
448	
449	    /**
450	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
451	     * or more owners, with 409 Conflict.
452	     *
453	     * @param owner the owner being created
454	     */
455	    private void rejectWhenCityAtCapacity(Owner owner) {
456	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
457	            throw new CityCapacityExceededException(
458	                "The city " + owner.getCity() + " already contains the maximum number of owners");
459	        }
460	    }
461	
462	    /**
463	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
464	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
465	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
466	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
467	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
468	     * server's current date. Canonicalising the address here, before the household checks read it,
469	     * ensures duplicate detection and the shared household id both compare the normalized form.
470	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
471	     * duplicate, household and customer-code rules.
472	     *
473	     * @param owner the newly mapped owner to canonicalize
474	     */
475	    private void normalizeOwnerFields(Owner owner) {
476	        // Canonicalize the owner's address fields on create so the address is stored and returned in
477	        // canonical form and every later comparison (household duplicate detection and the shared
478	        // household id) uses it. A value that is blank after normalization is rejected with 400.
479	        normalizeAddressFields(owner);
480	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
481	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
482	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
483	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
484	        // Store the (already syntactically validated) email lower-cased so it is persisted and
485	        // returned in canonical form. A missing email is left untouched.
486	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
487	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
488	        // canonicalization so the comparison sees the lower-cased value.
489	        rejectDisposableEmailDomain(owner.getEmail());
490	        // Validate the optional postcode against the fixed range for the city's region. A postcode
491	        // is checked only when present (it is optional); one out of range for the city's region is
492	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
493	        // value is left unchanged.
494	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
495	        // Reject a supplied registration date that is later than the server's current date with
496	        // 400, before any defaulting or business-day adjustment, so a future date is never
497	        // persisted regardless of how the roll-forward would move it.
498	        rejectFutureRegistrationDate(owner.getRegistrationDate());
499	        // Default the registration date to the server's current date when the client did not
500	        // supply one, then roll the effective date forward to a business day so a Saturday or
501	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
502	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
503	        // date-derived field (such as the membership number's year segment) and the per-day
504	        // create-limit are computed from.
505	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
506	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
507	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
508	    }
509	
510	    /**
511	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
512	     * returned in canonical form. The owner may supply its address in either of two forms and the
513	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
514	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
515	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
516	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
517	     * stored {@code address} is composed from the normalized structured lines when present — the
518	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
519	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
520	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
521	     * here, before the household checks read it, ensures duplicate detection and the shared household
522	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
523	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
524	     *
525	     * @param owner the newly mapped owner whose address is canonicalized
526	     */
527	    private void normalizeAddressFields(Owner owner) {
528	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
529	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
530	            owner.setAddressLine1(line1);
531	            String composed = line1;
532	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
533	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
534	                owner.setAddressLine2(line2);
535	                composed = line1 + " " + line2;
536	            }
537	            owner.setAddress(composed);
538	        }
539	        else {
540	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
541	        }
542	    }
543	
544	    /**
545	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
546	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
547	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
548	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
549	     * domain part is left untouched.
550	     *
551	     * @param email the owner's canonicalized email, or {@code null} when absent
552	     */
553	    private void rejectDisposableEmailDomain(String email) {
554	        if (email == null) {
555	            return;
556	        }
557	        int at = email.lastIndexOf('@');
558	        if (at < 0) {
559	            return;
560	        }
561	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
562	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
563	            throw new DisposableEmailException(
564	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
565	        }
566	    }
567	
568	    /**
569	     * Rejects a supplied registration date that is later than the server's current date with a
570	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
571	     * accepted, and a date on or before today is left for the normal defaulting and business-day
572	     * adjustment.
573	     *
574	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
575	     */
576	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
577	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
578	            throw new InvalidRegistrationDateException(
579	                "The supplied registration date " + registrationDate + " is later than the current date");
580	        }
581	    }
582	
583	    /**
584	     * The fixed list of public holidays. A registration date that lands on one of these dates is
585	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
586	     */
587	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
588	        java.time.LocalDate.of(2026, 1, 1),
589	        java.time.LocalDate.of(2026, 1, 26),
590	        java.time.LocalDate.of(2026, 4, 25),
591	        java.time.LocalDate.of(2026, 12, 25),
592	        java.time.LocalDate.of(2026, 12, 28));
593	
594	    /**
595	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
596	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
597	     * unchanged. Applied to the effective registration date (whether supplied in the request or
598	     * defaulted to the server date) so the persisted registration date, every value derived from it
599	     * and the per-day create-limit all use the adjusted business day.
600	     *
601	     * @param date the effective registration date
602	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
603	     */
604	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
605	        java.time.LocalDate adjusted = date;
606	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
607	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
608	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
609	            adjusted = adjusted.plusDays(1);
610	        }
611	        return adjusted;
612	    }
613	
614	    /**
615	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
616	     * region derived from the owner's postcode (falling back to the city, via
617	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
618	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
619	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
620	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
621	     * distinct customer codes.
622	     *
623	     * @param owner the owner being created, already normalized
624	     * @return the formatted, de-duplicated customer code
625	     */
626	    private String customerCode(Owner owner) {
627	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
628	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
629	        String base = region + "-" + hash8;
630	        Set<String> taken = existingOwners()
631	            .map(Owner::getCustomerCode)
632	            .filter(code -> code != null)
633	            .collect(Collectors.toSet());
634	        if (!taken.contains(base)) {
635	            return base;
636	        }
637	        int n = 2;
638	        while (taken.contains(base + "-" + n)) {
639	            n++;
640	        }
641	        return base + "-" + n;
642	    }
643	
644	    /**
645	     * Streams the existing owners that the create-time rules match a new owner against. Every
646	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
647	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
648	     * own matching criterion rather than on how the existing owners are retrieved.
649	     *
650	     * @return a stream over all existing owners
651	     */
652	    private Stream<Owner> existingOwners() {
653	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
654	        // new create, so the duplicate, identity and household checks (and the other create-time
655	        // scans built on this helper) ignore it.
656	        return this.clinicService.findAllOwners().stream()
657	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
658	    }
659	
660	    /**
661	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
662	     * fix the per-city sequence of an owner's customer code at creation time.
663	     *
664	     * @param city the city of the owner being created
665	     * @return the number of existing owners in a matching city
666	     */
667	    private int countOwnersInCity(String city) {
668	        return (int) existingOwners()
669	            .filter(existing -> existing.getCity() != null
670	                && existing.getCity().equalsIgnoreCase(city))
671	            .count();
672	    }
673	
674	    /**
675	     * Counts the existing owners whose registration date is the given adjusted business day. Used
676	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
677	     * owners already carry that business day as their registration date.
678	     *
679	     * @param date the adjusted business-day registration date to match
680	     * @return the number of existing owners registered on that date
681	     */
682	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
683	        return (int) existingOwners()
684	            .filter(existing -> date.equals(existing.getRegistrationDate()))
685	            .count();
686	    }
687	
688	    /**
689	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
690	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
691	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
692	     * after 1 July carries the following calendar year's fiscal year.
693	     *
694	     * @param customerCode     the owner's customer code
695	     * @param registrationDate the owner's registration date
696	     * @return the formatted membership number
697	     */
698	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
699	        return String.format("%s-M%02d",
700	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
701	    }
702	
703	    /**
704	     * Returns the existing owners in the given owner's household, i.e. those sharing its
705	     * deterministic household id (the same last name and postcode). The id is computed via
706	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
707	     * whitespace are treated as the same household. Centralising how "the same household" is matched
708	     * here keeps that definition in one place for every caller.
709	     *
710	     * @param owner the owner being created, with its household id already assigned
711	     * @return the existing owners in the owner's household (possibly empty)
712	     */
713	    private List<Owner> sameHouseholdOwners(Owner owner) {
714	        String householdId = owner.getHouseholdId();
715	        return existingOwners()
716	            .filter(existing -> householdId.equals(
717	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
718	            .toList();
719	    }
720	
721	    /**
722	     * Counts the existing owners who share the given first and last name, compared
723	     * case-insensitively. Used to fix an owner's namesake count at creation time.
724	     *
725	     * @param firstName the first name of the owner being created
726	     * @param lastName  the last name of the owner being created
727	     * @return the number of existing owners with a matching first and last name
728	     */
729	    private int countNamesakes(String firstName, String lastName) {
730	        return (int) existingOwners()
731	            .filter(existing -> existing.getFirstName() != null
732	                && existing.getFirstName().equalsIgnoreCase(firstName)
733	                && existing.getLastName() != null
734	                && existing.getLastName().equalsIgnoreCase(lastName))
735	            .count();
736	    }
737	
738	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
739	    @Override
740	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
741	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
742	        if (currentOwner == null) {
743	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
744	        }
745	        currentOwner.setAddress(ownerFieldsDto.getAddress());
746	        currentOwner.setCity(ownerFieldsDto.getCity());
747	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
748	        currentOwner.setLastName(ownerFieldsDto.getLastName());
749	        // Normalize the telephone to canonical E.164 form so it is stored and returned
750	        // consistently with create; an unformattable value is rejected with 400.
751	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
752	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
753	        this.clinicService.saveOwner(currentOwner);
754	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
755	    }
756	
757	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
758	    @Transactional
759	    @Override
760	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
761	        Owner owner = this.clinicService.findOwnerById(ownerId);
762	        if (owner == null) {
763	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
764	        }
765	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
766	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
767	        // duplicate and identity checks (see existingOwners()).
768	        owner.setDeleted(true);
769	        this.clinicService.saveOwner(owner);
770	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
771	    }
772	
773	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
774	    @Override
775	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
776	        Owner owner = this.clinicService.findOwnerById(ownerId);
777	        if (owner == null) {
778	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
779	        }
780	        HttpHeaders headers = new HttpHeaders();
781	        Pet pet = petMapper.toPet(petFieldsDto);
782	        owner.setId(ownerId);
783	        pet.setOwner(owner);
784	        pet.getType().setName(null);
785	        this.clinicService.savePet(pet);
786	        PetDto petDto = petMapper.toPetDto(pet);
787	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
788	            .buildAndExpand(pet.getId()).toUri());
789	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
790	    }
791	
792	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
793	    @Override
794	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
795	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
796	        if (currentOwner != null) {
797	            Pet currentPet = this.clinicService.findPetById(petId);
798	            if (currentPet != null) {
799	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
800	                currentPet.setName(petFieldsDto.getName());
801	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
802	                this.clinicService.savePet(currentPet);
803	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
804	            }
805	        }
806	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
807	    }
808	
809	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
810	    @Override
811	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
812	        HttpHeaders headers = new HttpHeaders();
813	        Visit visit = visitMapper.toVisit(visitFieldsDto);
814	        Pet pet = new Pet();
815	        pet.setId(petId);
816	        visit.setPet(pet);
817	        this.clinicService.saveVisit(visit);
818	        VisitDto visitDto = visitMapper.toVisitDto(visit);
819	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
820	            .buildAndExpand(visit.getId()).toUri());
821	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
822	    }
823	
824	
825	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
826	    @Override
827	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
828	        Owner owner = this.clinicService.findOwnerById(ownerId);
829	        if (owner != null) {
830	            Pet pet = owner.getPet(petId);
831	            if (pet != null) {
832	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
833	            }
834	        }
835	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
836	    }
837	}
